wp_register_ability_category(
	'wpbp-content',
	array(
		'label'       => __( 'Content', 'wpbp' ),
		'description' => __( 'Content manipulation and analysis abilities.', 'wpbp' ),
	)
);

wp_register_ability(
	'wpbp/count-words',
	array(
		'label'               => __( 'Count Words', 'wpbp' ),
		'description'         => __( 'Counts the number of words in the supplied text.', 'wpbp' ),
		'category'            => 'wpbp-content',
		'input_schema'        => array(
			'type'                 => 'object',
			'properties'           => array(
				'text' => array(
					'type'        => 'string',
					'description' => __( 'The text in which to count words.', 'wpbp' ),
				),
			),
			'required'             => array( 'text' ),
			'additionalProperties' => false,
		),
		'output_schema'       => array(
			'type'        => 'integer',
			'description' => __( 'The total number of words in the text.', 'wpbp' ),
		),
		'execute_callback'    => function ( $input ) {
			if ( ! is_array( $input ) || ! isset( $input['text'] ) || ! is_string( $input['text'] ) ) {
				return 0;
			}

			$clean_text = trim( wp_strip_all_tags( $input['text'] ) );

			if ( '' === $clean_text ) {
				return 0;
			}

			$words = preg_split( '/\s+/u', $clean_text, -1, PREG_SPLIT_NO_EMPTY );

			return is_array( $words ) ? count( $words ) : 0;
		},
		'permission_callback' => '__return_true',
		'meta'                => array(
			'annotations' => array(
				'readonly'    => true,
				'destructive' => false,
				'idempotent'  => true,
			),
		),
	)
);
