<?php

/**
 * Executes the 'wpbp/uppercase' ability with the supplied input.
 *
 * @param mixed $input The input to pass to the ability.
 * @return mixed|string The ability's result on success, or the WP_Error code string on failure.
 */
function wpbp_abilities_api_006( $input ) {
	$ability = wp_get_ability( 'wpbp/uppercase' );

	if ( is_wp_error( $ability ) ) {
		return $ability->get_error_code();
	}

	if ( ! $ability ) {
		return 'ability_not_found';
	}

	$result = $ability->execute( $input );

	if ( is_wp_error( $result ) ) {
		return $result->get_error_code();
	}

	return $result;
}
