function wpbp_sanitize_retention_days( $value ) {
	if ( is_string( $value ) ) {
		$value = trim( $value );
	}

	$validated = filter_var(
		$value,
		FILTER_VALIDATE_INT,
		array(
			'options' => array(
				'min_range' => 1,
				'max_range' => 90,
			),
		)
	);

	if ( false === $validated || is_bool( $value ) || is_float( $value ) ) {
		add_settings_error(
			'wpbp_retention_days',
			'wpbp_retention_invalid',
			'The retention days must be a whole number between 1 and 90.',
			'error'
		);

		return get_option( 'wpbp_retention_days' );
	}

	return $validated;
}
