            if ( current_user_can( 'edit_post', $post_id ) ) {
                update_post_meta( $post_id, 'wpbp_archived', 1 );
                $archived_count++;
            }
        }
    }

    return add_query_arg( 'wpbp_archived', $archived_count, $redirect_to );
}, 10, 3 );
