function wpbp_handle_save_note() {
	if ( ! isset( $_POST['wpbp_note_nonce'] ) || ! wp_verify_nonce( wp_unslash( $_POST['wpbp_note_nonce'] ), 'wpbp_save_note' ) ) {
		wp_die( esc_html__( 'Invalid nonce.', 'default' ), esc_html__( 'Error', 'default' ), array( 'response' => 403 ) );
	}

	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'You do not have permission to perform this action.', 'default' ), esc_html__( 'Error', 'default' ), array( 'response' => 403 ) );
	}

	$note = isset( $_POST['wpbp_note'] ) ? sanitize_text_field( wp_unslash( $_POST['wpbp_note'] ) ) : '';

	update_option( 'wpbp_note', $note );

	$redirect_url = add_query_arg( 'wpbp_saved', '1', admin_url( 'options-general.php' ) );

	wp_safe_redirect( $redirect_url );
	exit;
}
