add_filter( 'site_status_tests', 'wpbp_register_backup_freshness_site_health_test' );

/**
 * Registers the backup freshness check in the Site Health tests list.
 *
 * @param array $tests Existing Site Health tests.
 * @return array Modified Site Health tests.
 */
function wpbp_register_backup_freshness_site_health_test( $tests ) {
	$tests['direct']['wpbp_backup_freshness'] = array(
		'label' => __( 'Backup Freshness', 'wpbp' ),
		'test'  => 'wpbp_run_backup_freshness_site_health_test',
	);

	return $tests;
}

/**
 * Executes the backup freshness Site Health check.
 *
 * @return array Site Health test result data.
 */
function wpbp_run_backup_freshness_site_health_test() {
	$last_backup = get_option( 'wpbp_last_backup', 0 );
	$is_fresh    = is_numeric( $last_backup ) && (int) $last_backup > 0 && ( time() - (int) $last_backup ) < ( 7 * DAY_IN_SECONDS );

	$result = array(
		'label'       => __( 'A recent backup is available', 'wpbp' ),
		'status'      => 'good',
		'badge'       => array(
			'label' => __( 'Security', 'wpbp' ),
			'color' => 'blue',
		),
		'description' => sprintf(
			'<p>%s</p>',
			__( 'Your site has been backed up within the last 7 days.', 'wpbp' )
		),
		'actions'     => '',
		'test'        => 'wpbp_backup_freshness',
	);

	if ( ! $is_fresh ) {
		$result['label']       = __( 'Your site does not have a recent backup', 'wpbp' );
		$result['status']      = 'recommended';
		$result['badge']       = array(
			'label' => __( 'Security', 'wpbp' ),
			'color' => 'orange',
		);
		$result['description'] = sprintf(
			'<p>%s</p>',
			__( 'Your last recorded backup is older than 7 days or has never run. Regular backups help protect your site against data loss.', 'wpbp' )
		);
	}

	return $result;
}
