<?php

/**
 * Prevent suspended users from authenticating.
 *
 * Hooks into the 'authenticate' filter at priority 30, running after WordPress
 * core's wp_authenticate_username_password and wp_authenticate_email_password
 * checks (which run at priority 20).
 *
 * @param null|WP_User|WP_Error $user     WP_User if the user is authenticated, WP_Error or null otherwise.
 * @param string                $username Username or email address.
 * @param string                $password User password.
 * @return null|WP_User|WP_Error
 */
function wpbp_block_suspended_user_authentication( $user, $username, $password ) {
	if ( ! ( $user instanceof WP_User ) ) {
		return $user;
	}

	$is_suspended = get_user_meta( $user->ID, 'wpbp_suspended', true );

	if ( '1' === (string) $is_suspended ) {
		return new WP_Error(
			'wpbp_suspended',
			__( '<strong>Error:</strong> Your account has been suspended.' )
		);
	}

	return $user;
}

add_filter( 'authenticate', 'wpbp_block_suspended_user_authentication', 30, 3 );
