<?php

/**
 * Logs out a user from all sessions except the one identified by the supplied token.
 *
 * @param int    $user_id       The ID of the user.
 * @param string $token_to_keep The session token to preserve.
 * @return int The number of sessions that were ended.
 */
function wpbp_auth_004( int $user_id, string $token_to_keep ): int {
	if ( $user_id <= 0 ) {
		return 0;
	}

	$manager        = WP_Session_Tokens::get_instance( $user_id );
	$before_count   = count( $manager->get_all() );

	$manager->destroy_others( $token_to_keep );

	$after_count    = count( $manager->get_all() );

	return max( 0, $before_count - $after_count );
}
