<?php

/**
 * Checks a submitted password against a user's stored password hash and upgrades legacy hashes on the way.
 *
 * @param int    $user_id  The ID of the user.
 * @param string $password The plaintext password to verify.
 * @return string One of 'invalid', 'rehashed', or 'current'.
 */
function wpbp_auth_005( int $user_id, string $password ): string {
	$user = get_userdata( $user_id );

	if ( ! $user instanceof WP_User ) {
		return 'invalid';
	}

	$stored_hash = $user->user_pass;

	if ( ! wp_check_password( $password, $stored_hash, $user_id ) ) {
		return 'invalid';
	}

	if ( wp_password_needs_rehash( $stored_hash, $user_id ) ) {
		wp_set_password( $password, $user_id );
		return 'rehashed';
	}

	return 'current';
}
