add_filter( 'registration_errors', function ( $errors, $sanitized_user_login, $user_email ) {
	if ( ! is_string( $user_email ) || false === strpos( $user_email, '@' ) ) {
		return $errors;
	}

	$blocked_domains = get_option( 'wpbp_blocked_domains', array() );
	if ( ! is_array( $blocked_domains ) || empty( $blocked_domains ) ) {
		return $errors;
	}

	$domain = strtolower( substr( strrchr( trim( $user_email ), '@' ), 1 ) );

	if ( in_array( $domain, $blocked_domains, true ) ) {
		if ( ! is_wp_error( $errors ) ) {
