<?php

function wpbp_caching_009( string $counter_key ): int {
	$group = 'wpbp_counters';

	if ( wp_cache_add( $counter_key, 1, $group ) ) {
		return 1;
	}

	$new_count = wp_cache_incr( $counter_key, 1, $group );

	if ( false === $new_count ) {
		$current   = (int) wp_cache_get( $counter_key, $group );
		$new_count = $current + 1;
		wp_cache_set( $counter_key, $new_count, $group );
	}

	return (int) $new_count;
}
