/**
 * Returns user IDs whose user meta for a supplied key exactly matches the supplied value.
 *
 * @param string $meta_key   The user meta key to search for.
 * @param string $meta_value The exact user meta value to match.
 * @return array<int>        An array of matching user IDs.
 */
function wpbp_comments_users_002( string $meta_key, string $meta_value ): array {
	if ( '' === $meta_key ) {
		return array();
	}

	$user_query = new WP_User_Query(
		array(
			'fields'      => 'ID',
			'number'      => -1,
			'count_total' => false,
			'meta_query'  => array(
				array(
					'key'     => $meta_key,
					'value'   => $meta_value,
					'compare' => '=',
				),
			),
		)
	);

	$results = $user_query->get_results();

	if ( empty( $results ) || ! is_array( $results ) ) {
		return array();
	}

	return array_map( 'intval', $results );
}
