function wpbp_dates_time_004( int $post_id ): string {
	$timestamp = get_post_timestamp( $post_id, 'date' );

	if ( false === $timestamp ) {
		return '';
	}

	$now       = time();
	$time_diff = $now - $timestamp;

	if ( $time_diff >= 0 && $time_diff < WEEK_IN_SECONDS ) {
		return human_time_diff( $timestamp, $now ) . ' ago';
	}

	return (string) wp_date( get_option( 'date_format' ), $timestamp );
}
