<?php

/**
 * Counts each explicit block type in the supplied block markup using WP_Block_Processor.
 *
 * @param string $content The block markup to analyze.
 * @return array<string, int> An associative array keyed by fully qualified block names with their counts.
 */
function wpbp_gb_block_api_003( string $content ): array {
	$counts    = array();
	$processor = new WP_Block_Processor( $content );

	while ( $processor->next_block() ) {
		$block_type = $processor->get_block_type();

		if ( null === $block_type ) {
			continue;
		}

		if ( ! isset( $counts[ $block_type ] ) ) {
			$counts[ $block_type ] = 0;
		}

		++$counts[ $block_type ];
	}

	return $counts;
}
