<?php

function wpbp_block_api_013(): void {
	add_filter(
		'block_type_metadata',
		function ( array $metadata ): array {
			if ( empty( $metadata['name'] ) || ! is_string( $metadata['name'] ) ) {
				return $metadata;
			}

			if ( strpos( $metadata['name'], 'wpbp/' ) !== 0 ) {
				return $metadata;
			}

			if ( ! isset( $metadata['usesContext'] ) || ! is_array( $metadata['usesContext'] ) ) {
				$metadata['usesContext'] = array();
			}

			if ( ! in_array( 'postId', $metadata['usesContext'], true ) ) {
				$metadata['usesContext'][] = 'postId';
			}

			if ( ! isset( $metadata['supports'] ) || ! is_array( $metadata['supports'] ) ) {
				$metadata['supports'] = array();
			}

			if ( ! isset( $metadata['supports']['interactivity'] ) ) {
				$metadata['supports']['interactivity'] = array(
					'clientNavigation' => true,
				);
			} elseif ( is_array( $metadata['supports']['interactivity'] ) ) {
				$metadata['supports']['interactivity']['clientNavigation'] = true;
			} elseif ( true === $metadata['supports']['interactivity'] ) {
				// In WP 6.5+, interactivity: true implies interactivity support, 
				// to explicitly declare clientNavigation while keeping interactivity support:
				$metadata['supports']['interactivity'] = array(
					'interactive'      => true,
					'clientNavigation' => true,
				);
			} else {
				$metadata['supports']['interactivity'] = array(
					'clientNavigation' => true,
				);
			}

			return $metadata;
		}
	);
}

