<?php

function wpbp_gb_block_bindings_006( int $pattern_id, array $overrides ): string {
	$content = array();

	foreach ( $overrides as $block_name => $replacement_text ) {
		if ( ! is_string( $block_name ) || '' === $block_name ) {
			continue;
		}

		if ( is_array( $replacement_text ) ) {
			$content[ $block_name ] = $replacement_text;
		} elseif ( is_scalar( $replacement_text ) || ( is_object( $replacement_text ) && method_exists( $replacement_text, '__toString' ) ) ) {
			$content[ $block_name ] = array(
				'content' => (string) $replacement_text,
			);
		}
	}

	$attrs = array(
		'ref' => $pattern_id,
	);

	if ( ! empty( $content ) ) {
		$attrs['content'] = $content;
	}

	$block = array(
		'blockName'    => 'core/block',
		'attrs'        => $attrs,
		'innerBlocks'  => array(),
		'innerHTML'    => '',
		'innerContent' => array(),
	);

	return render_block( $block );
}
