function wpbp_hooks_008( string $hook, callable $callback, int $new_priority ) {
	global $wp_filter;

	$old_priority = has_filter( $hook, $callback );

	if ( false === $old_priority ) {
		return false;
	}

	$accepted_args = 1;
	$unique_id     = _wp_filter_build_unique_id( $hook, $callback, $old_priority );

