<?php

/**
 * Strips the style attribute and all inline event-handler attributes (on*)
 * from all HTML elements using the WordPress HTML API.
 *
 * @param string $html The untrusted HTML markup.
 * @return string The sanitized HTML markup.
 */
function wpbp_html_api_008( string $html ): string {
	$processor = new WP_HTML_Tag_Processor( $html );

	while ( $processor->next_tag() ) {
		// Remove the style attribute (remove_attribute is case-insensitive).
		$processor->remove_attribute( 'style' );

		// Find all attributes starting with "on" (get_attribute_names_with_prefix is case-insensitive and returns lowercase names).
		$event_attributes = $processor->get_attribute_names_with_prefix( 'on' );

		if ( is_array( $event_attributes ) ) {
			foreach ( $event_attributes as $attr_name ) {
				$processor->remove_attribute( $attr_name );
			}
		}
	}

	return $processor->get_updated_html();
}
