	$comments  = array();

	while ( $processor->next_token() ) {
		$token_type = $processor->get_token_type();

		if ( '#comment' !== $token_type && '#funky-comment' !== $token_type ) {
			continue;
		}

		$text = $processor->get_full_comment_text();
		if ( null === $text ) {
			$text = (string) $processor->get_modifiable_text();
		}

		if ( str_starts_with( $text, ' wp:' ) || str_starts_with( $text, ' /wp:' ) ) {
			continue;
		}

		$comments[] = array(
			'type'         => $token_type,
			'comment_type' => $processor->get_comment_type(),
			'text'         => $text,
		);
	}

	return $comments;
}
