function wpbp_html_api_010( string $raw_href ): bool {
	$decoded = WP_HTML_Decoder::decode_attribute( $raw_href );

	// According to the WHATWG URL Standard, leading and trailing C0 controls (U+0000 to U+001F)
	// and spaces (U+0020) are stripped from the input, and ASCII tab or newline characters
	// (\t, \n, \r) are removed from the input before parsing the scheme.
	$trimmed   = trim( $decoded, "\x00..\x20" );
	$sanitized = str_replace( array( "\t", "\n", "\r" ), '', $trimmed );

	return WP_HTML_Decoder::leads_with_bytes( $sanitized, 'javascript:', 'ascii-case-insensitive' );
}
