        } elseif ( is_string( $parsed_args['headers'] ) ) {
            $parsed = WP_Http::processHeaders( $parsed_args['headers'] );
            $parsed_args['headers'] = $parsed['headers'] ?? [];
        } elseif ( $parsed_args['headers'] instanceof \Traversable ) {
            $parsed_args['headers'] = iterator_to_array( $parsed_args['headers'] );
