	$response = wp_remote_get( $url );

	if ( is_wp_error( $response ) ) {
		return array(
			'message' => '',
			'session' => '',
			'cookies' => array(),
		);
	}

	$message = wp_remote_retrieve_response_message( $response );

	$session = wp_remote_retrieve_cookie_value( $response, 'wpbp_session' );

	$cookies_objects = wp_remote_retrieve_cookies( $response );
	$cookie_names    = array();

	if ( is_array( $cookies_objects ) ) {
		foreach ( $cookies_objects as $cookie ) {
			if ( $cookie instanceof WP_Http_Cookie && isset( $cookie->name ) ) {
				$cookie_names[] = (string) $cookie->name;
			} elseif ( is_object( $cookie ) && isset( $cookie->name ) ) {
				$cookie_names[] = (string) $cookie->name;
			}
		}
	}

	sort( $cookie_names, SORT_STRING );

	return array(
		'message' => (string) $message,
		'session' => (string) $session,
		'cookies' => $cookie_names,
	);
}
