<?php

function wpbp_http_api_008( string $url ): string {
    $transient_key = 'wpbp_http_' . md5( $url );
    $cached_body   = get_transient( $transient_key );

    if ( false !== $cached_body ) {
        return (string) $cached_body;
    }

    $response = wp_remote_get( $url );

    if ( is_wp_error( $response ) ) {
        return '';
    }

    $status_code = wp_remote_retrieve_response_code( $response );

    if ( 200 !== $status_code ) {
        return '';
    }

    $body = wp_remote_retrieve_body( $response );

    set_transient( $transient_key, $body, 5 * MINUTE_IN_SECONDS );

    return $body;
}
