<?php

function wpbp_mail_url_006( string $to, string $subject, string $message, string $from_email, string $from_name, string $attachment ): bool {
	$filter_email = static function () use ( $from_email ): string {
		return $from_email;
	};

	$filter_name = static function () use ( $from_name ): string {
		return $from_name;
	};

	add_filter( 'wp_mail_from', $filter_email );
	add_filter( 'wp_mail_from_name', $filter_name );

	try {
		$attachments = $attachment !== '' ? array( $attachment ) : array();
		$result      = wp_mail( $to, $subject, $message, '', $attachments );
	} finally {
		remove_filter( 'wp_mail_from', $filter_email );
		remove_filter( 'wp_mail_from_name', $filter_name );
	}

	return (bool) $result;
}
