<?php

function wpbp_media_004( string $file ): string {
	if ( ! file_exists( $file ) ) {
		return '';
	}

	if ( ! function_exists( 'wp_read_image_metadata' ) ) {
		require_once ABSPATH . 'wp-admin/includes/image.php';
	}

	if ( function_exists( 'wp_get_image_alttext' ) ) {
		$alt = wp_get_image_alttext( $file );
		return is_string( $alt ) ? trim( $alt ) : '';
	}

	$meta = wp_read_image_metadata( $file );

	if ( is_array( $meta ) ) {
		if ( ! empty( $meta['alt'] ) && is_string( $meta['alt'] ) ) {
			return trim( $meta['alt'] );
		}
		if ( ! empty( $meta['caption'] ) && is_string( $meta['caption'] ) ) {
			return trim( $meta['caption'] );
		}
		if ( ! empty( $meta['title'] ) && is_string( $meta['title'] ) ) {
			return trim( $meta['title'] );
		}
	}

	return '';
}
