/**
 * Plugin Name: WPBP Reader
 * Description: Manages reader settings across its lifecycle.
 * Version: 2.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Return the default settings for version 2.
 *
 * @return array
 */
function wpbp_reader_get_default_settings() {
	return array(
		'version'     => 2,
		'per_page'    => 10,
		'show_covers' => true,
	);
}

/**
 * Activation callback: seed default settings without overwriting existing ones.
 *
 * @return void
 */
function wpbp_reader_activate() {
	if ( false === get_option( 'wpbp_reader_settings', false ) ) {
		add_option( 'wpbp_reader_settings', wpbp_reader_get_default_settings() );
	}
	register_uninstall_hook( __FILE__, 'wpbp_reader_uninstall' );
}

/**
 * Upgrade check triggered on plugins_loaded.
 *
 * @return void
 */
function wpbp_reader_maybe_upgrade() {
	$settings = get_option( 'wpbp_reader_settings', false );
	if ( ! is_array( $settings ) ) {
		return;
	}

	$version = isset( $settings['version'] ) ? (int) $settings['version'] : 1;

	if ( $version >= 2 ) {
		return;
	}

	$defaults = wpbp_reader_get_default_settings();

	$per_page = $defaults['per_page'];
	if ( isset( $settings['per_page'] ) ) {
		$per_page = (int) $settings['per_page'];
	} elseif ( isset( $settings['perPage'] ) ) {
		$per_page = (int) $settings['perPage'];
	}

	$show_covers = isset( $settings['show_covers'] ) ? (bool) $settings['show_covers'] : $defaults['show_covers'];

	$upgraded_settings = array(
		'version'     => 2,
		'per_page'    => $per_page,
		'show_covers' => $show_covers,
	);

	update_option( 'wpbp_reader_settings', $upgraded_settings );

	$upgrades = (int) get_option( 'wpbp_reader_upgrades', 0 );
	update_option( 'wpbp_reader_upgrades', $upgrades + 1 );
}

/**
 * Uninstall callback: clean up stored plugin options.
 *
 * @return void
 */
function wpbp_reader_uninstall() {
	delete_option( 'wpbp_reader_settings' );
	delete_option( 'wpbp_reader_upgrades' );
}

register_activation_hook( __FILE__, 'wpbp_reader_activate' );
register_uninstall_hook( __FILE__, 'wpbp_reader_uninstall' );
add_action( 'plugins_loaded', 'wpbp_reader_maybe_upgrade' );
"}}

