		'taxonomy' => '',
	);

	$inserted = wp_insert_term( $name, $taxonomy );

	if ( ! is_wp_error( $inserted ) ) {
		$term = get_term( $inserted['term_id'], $taxonomy );

		if ( $term instanceof WP_Term ) {
			$result = array(
				'slug'     => $term->slug,
				'taxonomy' => $term->taxonomy,
			);
