<?php

/**
 * Adds the given category term IDs to a post without removing existing categories.
 *
 * @param int   $post_id  The ID of the post.
 * @param array $term_ids An array of category term IDs to assign.
 * @return array An array of term_taxonomy_ids of the affected terms.
 */
function wpbp_post_types_taxonomy_006( int $post_id, array $term_ids ): array {
	// Ensure all term IDs are strictly integers so WordPress treats them as IDs rather than slugs/names.
	$sanitized_term_ids = array_map( 'intval', $term_ids );

	// Set the object terms, passing true to append and preserve existing relationships.
	$result = wp_set_object_terms( $post_id, $sanitized_term_ids, 'category', true );

	if ( is_wp_error( $result ) || ! is_array( $result ) ) {
		return array();
	}

	return $result;
}
