<?php

function wpbp_post_types_taxonomy_009( int $post_id, array $submitted_term_ids ): array {
	$taxonomy = 'wpbp_ptt_topic';

	// Cast submitted strings to integers so wp_set_object_terms treats them as term IDs
	// instead of new term names/slugs, ensuring no new terms are created.
	$term_ids = array_map( 'intval', $submitted_term_ids );
	$term_ids = array_filter( $term_ids, function ( int $id ) use ( $taxonomy ): bool {
		return $id > 0 && term_exists( $id, $taxonomy ) !== null;
	} );

	wp_set_object_terms( $post_id, array_values( $term_ids ), $taxonomy, false );

	$assigned_terms = wp_get_object_terms( $post_id, $taxonomy, array( 'fields' => 'ids' ) );

	if ( is_wp_error( $assigned_terms ) || ! is_array( $assigned_terms ) ) {
		return array();
	}

	return array_map( 'intval', $assigned_terms );
}
