	if ( is_wp_error( $inserted ) ) {
		$existing_id = $inserted->get_error_data( 'term_exists' );
		if ( $existing_id ) {
			return (int) $existing_id;
		}
		return 0;
	}

	return (int) $inserted['term_id'];
}
