<?php

/**
 * Return the IDs of a category's ancestor categories ordered from top-level down to immediate parent.
 *
 * @param int $term_id The category term ID.
 * @return array<int> Array of ancestor term IDs as plain integers.
 */
function wpbp_post_types_taxonomy_013( int $term_id ): array {
	if ( $term_id <= 0 ) {
		return array();
	}

	$ancestors = get_ancestors( $term_id, 'category', 'taxonomy' );

	if ( empty( $ancestors ) || ! is_array( $ancestors ) ) {
		return array();
	}

	// get_ancestors() returns from lowest (immediate parent) to highest (top-level).
	// Reverse it so top-level is first and immediate parent is last.
	$ancestors = array_reverse( $ancestors );

	return array_map( 'intval', $ancestors );
}
