/**
 * Restore a trashed post to the status it held when trashed and return the resulting status.
 *
 * @param int $post_id The ID of the trashed post to restore.
 * @return string The post's status after restoration.
 */
function wpbp_posts_lifecycle_004( int $post_id ): string {
	$filter = static function ( string $new_status, int $current_post_id, string $previous_status ) use ( $post_id ): string {
		if ( $current_post_id === $post_id && '' !== $previous_status ) {
			return $previous_status;
		}
		return $new_status;
	};

	add_filter( 'wp_untrash_post_status', $filter, 10, 3 );

	try {
		wp_untrash_post( $post_id );
	} finally {
		remove_filter( 'wp_untrash_post_status', $filter, 10 );
	}

	$status = get_post_status( $post_id );

	return is_string( $status ) ? $status : '';
}
