/**
 * Queries terms for a supplied taxonomy with hide_empty disabled.
 *
 * @param string $taxonomy The taxonomy slug to query.
 * @return array Array of WP_Term objects or an empty array if none found or on error.
 */
function wpbp_queries_008( string $taxonomy ): array {
	if ( empty( $taxonomy ) || ! taxonomy_exists( $taxonomy ) ) {
		return array();
	}

	$query = new WP_Term_Query(
		array(
			'taxonomy'   => $taxonomy,
			'hide_empty' => false,
			'orderby'    => 'term_id',
			'order'      => 'ASC',
		)
	);

	$terms = $query->get_terms();

	if ( is_wp_error( $terms ) || ! is_array( $terms ) ) {
		return array();
	}

	return array_values( $terms );
}
