/**
 * Builds a collection REST API response with pagination headers.
 *
 * @param array $items    The collection of items to return.
 * @param int   $total    The total number of items available.
 * @param int   $per_page The number of items returned per page.
 * @return WP_REST_Response The REST API response object.
 */
function wpbp_rest_api_007( array $items, int $total, int $per_page ): WP_REST_Response {
	$response = new WP_REST_Response( $items, 200 );

	$total_pages = $per_page > 0 ? (int) ceil( $total / $per_page ) : 0;

	if ( $total > 0 && 0 === $total_pages ) {
		$total_pages = 1;
	}

	$response->header( 'X-WP-Total', (string) $total );
	$response->header( 'X-WP-TotalPages', (string) $total_pages );

	return $response;
}
