/**
 * Returns the correct REST authorization status codes for logged-out and logged-in users.
 *
 * @return array<string, int>
 */
function wpbp_rest_api_011(): array {
	$original_user_id = get_current_user_id();

	// Test for logged-out user (typically 401).
	wp_set_current_user( 0 );
	$logged_out_status = rest_authorization_required_code();

	// Ensure a valid user ID exists to simulate a logged-in state.
	$users = get_users(
		array(
			'fields' => 'ID',
			'number' => 1,
		)
	);

	$temp_user_id = 0;
	if ( empty( $users ) ) {
		$created_id = wp_insert_user(
			array(
				'user_login' => 'wpbp_temp_user_' . wp_generate_password( 8, false ),
				'user_pass'  => wp_generate_password(),
				'role'       => 'subscriber',
			)
		);
		if ( ! is_wp_error( $created_id ) ) {
			$temp_user_id = $created_id;
			$test_user_id = $created_id;
		} else {
			$test_user_id = 1;
		}
	} else {
		$test_user_id = (int) $users[0];
	}

	// Test for logged-in user (typically 403).
	wp_set_current_user( $test_user_id );
	$logged_in_status = rest_authorization_required_code();

	// Restore original user state.
	wp_set_current_user( $original_user_id );

	// Clean up temporary user if one was created.
	if ( $temp_user_id > 0 ) {
		if ( ! function_exists( 'wp_delete_user' ) ) {
			require_once ABSPATH . 'wp-admin/includes/user.php';
		}
		wp_delete_user( $temp_user_id );
	}

	return array(
		'logged_out' => $logged_out_status,
		'logged_in'  => $logged_in_status,
	);
}
