<?php

class WPBP_Venues_Controller extends WP_REST_Controller {

	public function __construct() {
		$this->namespace = 'wpbp/v1';
		$this->rest_base = 'venues';
	}

	public function register_routes() {
		register_rest_route(
			$this->namespace,
			'/' . $this->rest_base,
			array(
				array(
					'methods'             => WP_REST_Server::READABLE,
					'callback'            => array( $this, 'get_items' ),
					'permission_callback' => array( $this, 'get_items_permissions_check' ),
					'args'                => array(
						'context' => $this->get_context_param(
							array(
								'default' => 'view',
								'enum'    => array( 'view', 'edit' ),
							)
						),
					),
				),
				'schema' => array( $this, 'get_public_item_schema' ),
			)
		);
	}

	public function get_items_permissions_check( $request ) {
		if ( 'edit' === $request['context'] && ! current_user_can( 'edit_posts' ) ) {
			return new WP_Error(
				'rest_forbidden_context',
				__( 'Sorry, you are not allowed to edit these items.' ),
				array( 'status' => rest_authorization_required_code() )
			);
		}

		return true;
	}

	public function get_items( $request ) {
		$venues = get_option( 'wpbp_venues', array() );

		if ( ! is_array( $venues ) ) {
			$venues = array();
		}

		$data = array();

		foreach ( $venues as $venue ) {
			$item_response = $this->prepare_item_for_response( (array) $venue, $request );
			$data[]        = $this->prepare_response_for_collection( $item_response );
		}

		return rest_ensure_response( $data );
	}

	public function prepare_item_for_response( $item, $request ) {
		$fields = $this->get_fields_for_response( $request );
		$data   = array();

		if ( rest_is_field_included( 'name', $fields ) ) {
			$data['name'] = isset( $item['name'] ) ? (string) $item['name'] : '';
		}

		if ( rest_is_field_included( 'capacity', $fields ) ) {
			$data['capacity'] = isset( $item['capacity'] ) ? (int) $item['capacity'] : 0;
		}

		if ( rest_is_field_included( 'owner_email', $fields ) ) {
			$data['owner_email'] = isset( $item['owner_email'] ) ? (string) $item['owner_email'] : '';
		}

		$context = ! empty( $request['context'] ) ? $request['context'] : 'view';
		$data    = $this->add_additional_fields_to_object( $data, $request );
		$data    = $this->filter_response_by_context( $data, $context );

		return rest_ensure_response( $data );
	}

	public function get_item_schema() {
		if ( $this->schema ) {
			return $this->add_additional_fields_schema( $this->schema );
		}

		$this->schema = array(
			'$schema'    => 'http://json-schema.org/draft-04/schema#',
			'title'      => 'venue',
			'type'       => 'object',
			'properties' => array(
				'name'        => array(
					'description' => __( 'The name of the venue.' ),
					'type'        => 'string',
					'context'     => array( 'view', 'edit' ),
					'readonly'    => true,
				),
				'capacity'    => array(
					'description' => __( 'The capacity of the venue.' ),
					'type'        => 'integer',
					'context'     => array( 'view', 'edit' ),
					'readonly'    => true,
				),
				'owner_email' => array(
					'description' => __( 'The email address of the venue owner.' ),
					'type'        => 'string',
					'format'      => 'email',
					'context'     => array( 'edit' ),
					'readonly'    => true,
				),
			),
		);

		return $this->add_additional_fields_schema( $this->schema );
	}
}

add_action(
	'rest_api_init',
	function () {
		$controller = new WPBP_Venues_Controller();
		$controller->register_routes();
	}
);
