        'permission_callback' => '__return_true',
        'args'                => [
            'id' => [
                'type'              => 'integer',
                'required'          => true,
                'sanitize_callback' => 'absint',
                'validate_callback' => function ( $param ) {
                    return is_numeric( $param );
                },
            ],
        ],
    ] );
} );

function wpbp_get_single_note( WP_REST_Request $request ) {
    $id    = (int) $request->get_param( 'id' );
    $notes = get_option( 'wpbp_notes', [] );

    if ( ! is_array( $notes ) || ! isset( $notes[ $id ] ) ) {
        return new WP_Error(
            'wpbp_note_not_found',
            'Note not found.',
            [ 'status' => 404 ]
        );
    }

    $note   = (array) $notes[ $id ];
    $title  = isset( $note['title'] ) ? (string) $note['title'] : '';
    $author = isset( $note['author'] ) ? (int) $note['author'] : 0;

    $data = [
        'id'     => $id,
        'title'  => $title,
        'author' => $author,
    ];

    $response = new WP_REST_Response( $data, 200 );

    $response->add_link(
        'self',
        rest_url( sprintf( 'wpbp/v1/notes/%d', $id ) )
    );

    $response->add_link(
        'author',
        rest_url( sprintf( 'wp/v2/users/%d', $author ) ),
        [ 'embeddable' => true ]
    );

    return $response;
}
