	register_rest_route( 'wpbp/v1', '/bookings', array(
		'methods'             => WP_REST_Server::CREATABLE,
		'permission_callback' => '__return_true',
		'args'                => array(
			'room'   => array(
				'required' => true,
				'type'     => 'string',
				'enum'     => array( 'harbor', 'cedar' ),
			),
			'guests' => array(
				'type'    => 'integer',
				'default' => 2,
				'minimum' => 1,
			),
		),
		'callback'            => function ( WP_REST_Request $request ) {
			$room     = $request->get_param( 'room' );
			$guests   = (int) $request->get_param( 'guests' );
			$bookings = get_option( 'wpbp_bookings', array() );

			if ( ! is_array( $bookings ) ) {
				$bookings = array();
			}

			$errors     = new WP_Error();
			$room_taken = in_array( $room, $bookings, true );

			if ( $room_taken ) {
				$errors->add(
					'wpbp_room_taken',
					'This room is already booked.',
					array( 'status' => 409 )
				);
			}

			if ( $guests > 4 ) {
				$errors->add(
					'wpbp_over_capacity',
					'A room cannot hold more than 4 guests.',
					array( 'status' => $room_taken ? 409 : 422 )
				);
			}

			if ( $errors->has_errors() ) {
				return $errors;
			}

			$bookings[] = $room;
			update_option( 'wpbp_bookings', $bookings );

			return new WP_REST_Response(
				array(
					'room'   => $room,
					'guests' => $guests,
				),
				201
			);
		},
	) );
} );
