	register_rest_route( 'wpbp/v1', '/reports/(?P<id>\d+)', [
		'methods'             => WP_REST_Server::READABLE,
		'permission_callback' => '__return_true',
		'args'                => [
			'id' => [
				'required'          => true,
				'validate_callback' => function ( $param ) {
					return is_numeric( $param );
				},
				'sanitize_callback' => 'absint',
			],
		],
		'callback'            => function ( WP_REST_Request $request ) {
			$report_id = (int) $request['id'];
			$reports   = get_option( 'wpbp_reports', [] );

			if ( ! is_array( $reports ) || ! array_key_exists( $report_id, $reports ) ) {
				return new WP_Error(
					'rest_report_not_found',
					__( 'Report not found.' ),
					[ 'status' => 404 ]
				);
			}

			$fields = $request->get_param( '_fields' );
			if ( is_string( $fields ) ) {
				$requested_fields = array_map( 'trim', explode( ',', $fields ) );
			} elseif ( is_array( $fields ) ) {
				$requested_fields = array_map( 'trim', $fields );
			} else {
				$requested_fields = [ 'id', 'title', 'stats' ];
			}

			$data = [];

			if ( in_array( 'id', $requested_fields, true ) || rest_is_field_included( 'id', $requested_fields ) ) {
				$data['id'] = $report_id;
			}

			if ( in_array( 'title', $requested_fields, true ) || rest_is_field_included( 'title', $requested_fields ) ) {
				$data['title'] = $reports[ $report_id ];
			}

			if ( in_array( 'stats', $requested_fields, true ) || rest_is_field_included( 'stats', $requested_fields ) ) {
				$data['stats'] = wpbp_report_stats( $report_id );
			}

			return rest_ensure_response( $data );
		},
	] );
} );
