add_filter( 'rest_authentication_errors', function ( $result ) {
	if ( ! empty( $result ) ) {
		return $result;
	}

	if ( ! isset( $_SERVER['HTTP_X_WPBP_KEY'] ) ) {
		return $result;
	}

	$provided_key = wp_unslash( $_SERVER['HTTP_X_WPBP_KEY'] );
	$stored_key   = get_option( 'wpbp_api_key' );

	if ( ! is_string( $stored_key ) || '' === $stored_key || ! hash_equals( $stored_key, (string) $provided_key ) ) {
