			'wpbp_bad_key',
			'Invalid API key.',
			array( 'status' => 401 )
		);
	}

	$user_id = (int) get_option( 'wpbp_api_user' );
	if ( $user_id > 0 ) {
		wp_set_current_user( $user_id );
	}

	return true;
} );
