/**
 * Returns the normalized serialization of the first token in a WordPress HTML fragment.
 *
 * @param string $html The HTML fragment to process.
 * @return string The normalized serialization of the first token, or an empty string on failure.
 */
function wpbp_security_002( string $html ): string {
