<?php

add_filter( 'allowed_redirect_hosts', function ( array $hosts ): array {
	$partner_hosts = get_option( 'wpbp_redirect_hosts', array() );

	if ( is_string( $partner_hosts ) ) {
		$partner_hosts = preg_split( '/[\s,]+/', $partner_hosts, -1, PREG_SPLIT_NO_EMPTY );
	}

	if ( ! is_array( $partner_hosts ) ) {
		return $hosts;
	}

	foreach ( $partner_hosts as $host ) {
		if ( ! is_string( $host ) ) {
			continue;
		}

		$host = trim( $host );
		if ( '' === $host ) {
			continue;
		}

		if ( strpos( $host, '://' ) !== false ) {
			$parsed = wp_parse_url( $host, PHP_URL_HOST );
			$host   = is_string( $parsed ) ? $parsed : '';
		}

		$host = strtolower( trim( $host, '/' ) );

		if ( '' !== $host ) {
			$hosts[] = $host;
		}
	}

	return array_values( array_unique( $hosts ) );
}, 10, 1 );
