<?php

/**
 * Updates the 'wpbp_nested' option by storing a sanitized plain-text value
 * under a sanitized key while preserving existing entries.
 *
 * @param string $key   The array key to store the value under.
 * @param string $value The plain-text value to store.
 * @return array The full updated option array.
 */
function wpbp_settings_options_003( string $key, string $value ): array {
	$option_name = 'wpbp_nested';
	$options     = get_option( $option_name, array() );

	if ( ! is_array( $options ) ) {
		$options = array();
	}

	$sanitized_key   = sanitize_key( $key );
	$sanitized_value = sanitize_text_field( $value );

	if ( '' !== $sanitized_key ) {
		$options[ $sanitized_key ] = $sanitized_value;
		update_option( $option_name, $options );
	}

	return $options;
}
