<?php

/**
 * Resolves a block template for the active theme and returns its content and source.
 *
 * @param string $template_slug The slug of the template to resolve.
 * @return array{content: string, source: string}
 */
function wpbp_theme_templates_003( string $template_slug ): array {
	$template_id = get_stylesheet() . '//' . $template_slug;
	$template    = get_block_template( $template_id, 'wp_template' );

	if ( ! $template instanceof WP_Block_Template ) {
		return array(
			'content' => '',
			'source'  => '',
		);
	}

	return array(
		'content' => (string) $template->content,
		'source'  => (string) $template->source,
	);
}
