add_filter( 'the_content', function ( $content ) {
	if ( ! has_blocks( $content ) ) {
		return $content;
	}

	$blocks = parse_blocks( $content );

	$real_block_indices = array();
	foreach ( $blocks as $index => $block ) {
		if ( ! empty( $block['blockName'] ) ) {
			$real_block_indices[] = $index;
		}
	}

	if ( count( $real_block_indices ) <= 2 ) {
		return $content;
	}

	$second_real_block_index = $real_block_indices[1];

	$promo_block = array(
		'blockName'    => 'core/paragraph',
		'attrs'        => array(
			'className' => 'wpbp-promo',
		),
		'innerBlocks'  => array(),
		'innerHTML'    => '<p class="wpbp-promo">Sponsored by WPBP</p>',
		'innerContent' => array(
			'<p class="wpbp-promo">Sponsored by WPBP</p>',
		),
	);

	array_splice( $blocks, $second_real_block_index + 1, 0, array( $promo_block ) );

	$output = '';
	foreach ( $blocks as $block ) {
		$output .= render_block( $block );
	}

	return $output;
}, 8 );
