<?php

class WPBP_Recent_Items_Widget extends WP_Widget {

	public function __construct() {
		parent::__construct(
			'wpbp-recent-items',
			__( 'WPBP Recent Items', 'textdomain' ),
			array(
				'description' => __( 'Lists a site\'s most recent published entries.', 'textdomain' ),
			)
		);
	}

	public function widget( $args, $instance ) {
		$title     = ! empty( $instance['title'] ) ? $instance['title'] : '';
		$post_type = ! empty( $instance['post_type'] ) ? $instance['post_type'] : 'post';
		$number    = ! empty( $instance['number'] ) ? absint( $instance['number'] ) : 3;
		if ( ! $number ) {
			$number = 3;
		}

		echo isset( $args['before_widget'] ) ? $args['before_widget'] : '';

		if ( '' !== $title ) {
			$filtered_title = apply_filters( 'widget_title', $title, $instance, $this->id_base );
			if ( '' !== $filtered_title ) {
				echo ( isset( $args['before_title'] ) ? $args['before_title'] : '' ) . $filtered_title . ( isset( $args['after_title'] ) ? $args['after_title'] : '' );
			}
		}

		$recent_posts = get_posts(
			array(
				'post_type'           => $post_type,
				'posts_per_page'      => $number,
				'post_status'         => 'publish',
				'ignore_sticky_posts' => true,
				'no_found_rows'       => true,
				'orderby'             => 'date',
				'order'               => 'DESC',
			)
		);

		echo '<ul>';
		if ( ! empty( $recent_posts ) ) {
			foreach ( $recent_posts as $recent_post ) {
				$post_title = get_the_title( $recent_post );
				$title_text = ( ! empty( $post_title ) ) ? $post_title : __( '(no title)', 'textdomain' );
				$permalink  = get_permalink( $recent_post );
				echo '<li><a href="' . esc_url( $permalink ) . '">' . esc_html( $title_text ) . '</a></li>';
			}
		}
		echo '</ul>';

		echo isset( $args['after_widget'] ) ? $args['after_widget'] : '';
	}

